  // Diplomacy: relations with Cancel / End war, proposals (Accept / Decline / Withdraw), and the New relation form.
  const rel = (k, l, rows) => `<div class="up sec">${l}</div>${rows.map(([t, n, sub, btn]) => `<div class="row2"><span class="dkk ${k}">${{ ally: 'Ally', nap: 'Non-aggression', enemy: 'Enemy' }[k]}</span><span class="mt"><b>[${t}] ${n}</b><small>${sub}</small></span><span class="btn sm${k === 'enemy' ? '' : ''}">${btn}</span></div>`).join('')}`;
